SELECT DATALENGTH(CAST('NV001' AS char(8))) AS [ByteChar],
	DATALENGTH(CAST('NV001' AS varchar(8))) AS [ByteVarchar],
	LEN(CAST('NV001' AS char(8))) AS [SoKyTu];

SELECT LEN(N'Hạnh') AS [SoKyTu],
	DATALENGTH(N'Hạnh') AS [SoByte],
	CAST(N'Hạnh' AS nvarchar(3)) AS [BiCat];

SELECT CAST('123.456' AS decimal(8,2)) AS [SoTien],
	TRY_CAST(N'chưa rõ' AS decimal(8,2)) AS [KhongDoiDuoc],
	TRY_CAST(NULL AS decimal(8,2)) AS [NguonNull];

SELECT PARSE(N'1.234,56' AS decimal(10,2) USING 'vi-VN') AS [SoTien],
	CONVERT(char(10), PARSE(N'31/10/2026' AS date USING 'vi-VN'), 23) AS [Ngay],
	TRY_PARSE(N'không rõ' AS decimal(10,2) USING 'vi-VN') AS [SoSai];

SELECT CAST(N'NV001' AS nvarchar(3)) AS [MaBiCat],
	CAST(12.345 AS decimal(5,2)) AS [LamTron],
	TRY_CAST(1000 AS decimal(5,2)) AS [Tran];

SELECT LEN(N' An ') AS [SoKyTu],
	DATALENGTH(N' An ') AS [SoByte],
	LEN(TRIM(N' An ')) AS [SauTrim];

SELECT CHARINDEX(N'@', N'an@example.com') AS [ViTri],
	CHARINDEX(N'@', N'khong-co-at') AS [KhongThay],
	PATINDEX(N'%[0-9]%', N'NV047') AS [ChuSoDau];

SELECT CONCAT(N'NV', 47, NULL) AS [Noi],
	CONCAT_WS(N' - ', N'NV047', NULL, N'Nhân sự') AS [BoNull],
	CONCAT_WS(N' - ', N'NV047', N'', N'Nhân sự') AS [GiuRong];

SELECT value AS [GiaTri], ordinal AS [ViTri]
FROM STRING_SPLIT(N'IT,,KT', N',', 1)
ORDER BY ordinal;

SELECT STRING_AGG(CAST(Ma AS nvarchar(max)), N', ')
	WITHIN GROUP (ORDER BY ThuTu) AS [DanhSach]
FROM (VALUES (2, N'KT'), (1, N'IT'), (3, NULL)) AS v(ThuTu, Ma);

SELECT CEILING(2.1) AS [LenDuong], FLOOR(2.1) AS [XuongDuong],
	CEILING(-2.1) AS [LenAm], FLOOR(-2.1) AS [XuongAm],
	ROUND(-2.1, 0, 1) AS [CatVeKhong];

SELECT SUM(ROUND(SoTien, 2)) AS [TronTungDong],
	ROUND(SUM(SoTien), 2) AS [TronTong]
FROM (VALUES (0.005), (0.005)) AS v(SoTien);

SELECT DATEDIFF(year, DATEFROMPARTS(2025, 12, 31), DATEFROMPARTS(2026, 1, 1)) AS [RanhGioiNam],
	DATEDIFF(day, DATEFROMPARTS(2025, 12, 31), DATEFROMPARTS(2026, 1, 1)) AS [RanhGioiNgay],
	DATEDIFF_BIG(millisecond, DATEFROMPARTS(2026, 1, 1), DATEFROMPARTS(2027, 1, 1)) AS [MiliGiay];

SELECT CONVERT(varchar(33),
	DATE_BUCKET(minute, 15, CAST('2026-10-21T10:17:00' AS datetime2(0)),
		CAST('2026-10-21T00:00:00' AS datetime2(0))), 126) AS [DauKhoang];

SELECT X
FROM (VALUES (1), (CAST(NULL AS int))) AS v(X)
WHERE X = NULL;

SELECT X
FROM (VALUES (1), (CAST(NULL AS int))) AS v(X)
WHERE X IS NULL;

SELECT ISNULL(CAST(NULL AS nvarchar(3)), N'Chưa có') AS [IsNull],
	COALESCE(CAST(NULL AS nvarchar(3)), N'Chưa có') AS [Coalesce],
	COALESCE(N'', N'Dự phòng') AS [ChuoiRong];

SELECT NULLIF(TRIM(N'   '), N'') AS [ChuoiThieu],
	10.0 / NULLIF(0, 0) AS [TyLe],
	NULLIF(5, 0) AS [GiuSo];
